/// Computes estimated runtime in hours given battery capacity (mAh),\n/// voltage (V), and device power consumption (W).\n///\n/// # Arguments\n/// * `capacity_mAh` - Battery capacity in milliamp‑hours.\n/// * `voltage` - Battery nominal voltage in volts.\n/// * `consumption_watts` - Power consumption of the device in watts.\n///\n/// # Returns\n/// Estimated runtime in hours as a `f64`.\npub fn compute_runtime(capacity_mAh: f64, voltage: f64, consumption_watts: f64) -> f64 {\n    let wh = capacity_mAh * voltage / 1000.0; // Convert mAh*V to Wh\n    wh / consumption_watts\n}\n
